// join-panel.js
// The same file sits in every class-11 projector folder. It does the plumbing every
// projector page needs, so sketch.js can be about the idea:
//   projectorSetup(room, title, sharedStart)  joins the room as the projector and shows the join code
//   layoutProjector()            works out the sizes. call it in setup() and windowResized()
//   drawTitle(line)              the title bar
//   drawJoinColumn(label, value, size)  the phone count, one more number, the join code and the
//                                       connection state. size is the text size of that number
//   phoneList()                  every guest that is a phone
//   nameOf(id)                   the name a phone picked for itself
//
// The rule for every class-wide example: Share keeps only the last thing written, so two phones
// that add 1 at the same moment count once. So each phone keeps its own value in me, the
// projector adds them up, and the projector is the only page that writes shared.

const AMBER = '#ffc800';
const GREY = '#9a9a9a';
const GREEN = '#5ce08a';
const RED = '#ff5a4d';

let u = 1;           // one design unit. 1 is a 1920 by 1080 screen. everything is sized with it
let qrSize = 300;    // the join code, in pixels
let colX = 0;        // the left edge of the column on the right
let colW = 300;      // its width
let arena = { x: 0, y: 0, w: 100, h: 100 }; // the space left over for the piece itself
let joinUrl = '';    // the address a phone opens. this is what the code holds
let shortUrl = '';   // the same address with no server in it, short enough to type
let serverProblem = ''; // what is wrong with the server address, or nothing
let hostName = '';
let roomName = '';
let projectorTitle = '';

// join the room. the page address can carry ?shareHost= and ?room= to change either one
function projectorSetup(room, title, sharedStart) {
  projectorTitle = title;
  textFont('system-ui');

  const fromUrl = new URLSearchParams(location.search).get('shareHost');
  const host = fromUrl || window.CLASS_SHARE_HOST || '';
  hostName = host.replace(/^https?:\/\//, '');
  if (!host || host.indexOf('REPLACE-ME') >= 0) {
    serverProblem = 'No server address yet';
    return false;
  }

  shareSetup({
    host: host,
    room: room,
    shared: sharedStart || {},
    me: { role: 'projector' }
  });
  roomName = window.shareRoom.replace(/^default:/, '');
  shareConnect().catch(function () {});

  // the phone page sits next to this one. getShareJoinUrl adds the server and the room
  const phonePage = new URL('https://digitalfuturesocadu.github.io/f26-atelier1-examples/class-11/02-chord/phone/');
  joinUrl = getShareJoinUrl(phonePage.href);
  // a colon and a slash are fine in a query. leaving them as they are makes the code smaller
  joinUrl = joinUrl.replace(/%3A/gi, ':').replace(/%2F/gi, '/');
  shortUrl = (phonePage.host + phonePage.pathname);
  layoutProjector();
  showJoinCode();
  return true;
}

function layoutProjector() {
  u = min(width / 1920, height / 1080);
  qrSize = round(constrain(min(height * 0.34, width * 0.22), 190, 420));
  colW = qrSize + 24;          // the code sits in a white panel with 12 pixels round it
  colX = width - 16 - colW;
  arena.x = 48 * u;
  arena.y = 150 * u;
  arena.w = colX - 48 * u - arena.x;
  arena.h = height - arena.y - 48 * u;
}

// p5-phone draws the code. it is a white panel in the bottom right corner
function showJoinCode() {
  if (!joinUrl) return;
  showDesktopQr({
    url: joinUrl,
    share: false,          // the address already carries the server and the room
    size: qrSize,
    position: 'bottom-right',
    label: '',
    closable: false,
    rememberDismiss: false
  });
}

function phoneList() {
  return guests.filter(function (g) {
    return g.role === 'phone';
  });
}

function nameOf(id) {
  for (let i = 0; i < guests.length; i++) {
    if (guests[i].id === id) {
      return guests[i].name || 'Someone';
    }
  }
  return 'Someone';
}

function drawTitle(line) {
  noStroke();
  fill(255);
  textAlign(LEFT, BASELINE);
  textStyle(BOLD);
  textSize(56 * u);
  text(projectorTitle, 48 * u, 84 * u);
  textStyle(NORMAL);
  fill(GREY);
  textSize(30 * u);
  text(line, 48 * u, 128 * u);
}

function connectionInfo() {
  if (serverProblem) {
    return { dot: RED, words: serverProblem };
  }
  if (shareConnected) {
    return { dot: GREEN, words: 'Connected' };
  }
  if (shareStatus === 'connecting' || shareStatus === 'idle') {
    return { dot: AMBER, words: 'Connecting' };
  }
  return { dot: RED, words: 'Cannot reach the server. Trying again' };
}

// the column on the right: how many phones, one more number, the state of the connection,
// and the code to join with
function drawJoinColumn(label, value, valueSize) {
  const x = colX;
  noStroke();
  textAlign(LEFT, BASELINE);

  fill(GREY);
  textSize(26 * u);
  text('PHONES', x, 58 * u);
  fill(255);
  textStyle(BOLD);
  textSize(150 * u);
  text(phoneList().length, x, 190 * u);
  textStyle(NORMAL);

  if (label) {
    fill(GREY);
    textSize(26 * u);
    text(label, x, 262 * u);
    fill(AMBER);
    textStyle(BOLD);
    textSize((valueSize || 96) * u);
    text(value, x, 352 * u);
    textStyle(NORMAL);
  }

  // the state of the connection
  const info = connectionInfo();
  fill(info.dot);
  circle(x + 9 * u, 400 * u, 18 * u);
  fill(255);
  textSize(28 * u);
  const said = wrapText(info.words, colW - 34 * u);
  for (let i = 0; i < said.length; i++) {
    text(said[i], x + 32 * u, 410 * u + i * 34 * u);
  }
  fill(GREY);
  textSize(22 * u);
  if (!serverProblem) {
    text('Room: ' + roomName, x, 410 * u + said.length * 34 * u + 14 * u);
  }

  // the address above the code
  const codeTop = height - 16 - (qrSize + 24);
  if (serverProblem) {
    fill(255);
    textSize(26 * u);
    const lines = wrapText('Put the server address in class-server.js. Or add ?shareHost=https://your-server.workers.dev to the end of this page address.', colW);
    for (let i = 0; i < lines.length; i++) {
      text(lines[i], x, codeTop - (lines.length - i) * 32 * u);
    }
    return;
  }
  textSize(22 * u);
  const lines = wrapText(shortUrl, colW);
  const lineH = 27 * u;
  const top = codeTop - 14 * u - lines.length * lineH;
  fill(AMBER);
  textStyle(BOLD);
  textSize(34 * u);
  text('SCAN TO JOIN', x, top - 14 * u);
  textStyle(NORMAL);
  fill(GREY);
  textSize(22 * u);
  for (let i = 0; i < lines.length; i++) {
    text(lines[i], x, top + (i + 1) * lineH - 6 * u);
  }
}

// break text into lines no wider than w. it breaks at a space or after a slash, and in the
// middle of a word only when the word is wider than the line. text size must be set first
function wrapText(str, w) {
  const parts = String(str).split(/(?<=[ \/])/);
  const lines = [];
  let line = '';
  for (let i = 0; i < parts.length; i++) {
    let part = parts[i];
    if (line && textWidth((line + part).trimEnd()) > w) {
      lines.push(line.trimEnd());
      line = '';
    }
    // a piece wider than the whole line is cut up
    while (textWidth(part.trimEnd()) > w && part.length > 1) {
      let n = part.length - 1;
      while (n > 1 && textWidth(part.slice(0, n)) > w) {
        n -= 1;
      }
      lines.push(part.slice(0, n));
      part = part.slice(n);
    }
    line += part;
  }
  if (line) {
    lines.push(line.trimEnd());
  }
  return lines;
}

// a small round arrow head for a line that ends at (x, y)
function arrowHead(x, y, angle, size) {
  push();
  translate(x, y);
  rotate(angle);
  triangle(0, 0, -size, size * 0.5, -size, -size * 0.5);
  pop();
}

// 02 Chord: Projector
// Share. The room is the instrument. This page gives every phone one note of a chord.
// Each phone plays its note, and the tilt of the phone sets how loud. Raise a phone and its
// note gets louder. Lay it flat and it goes quiet. This page makes no sound. The sound is
// in the room, from every phone.
//
// The rule: Share keeps only the last thing written, so each phone keeps its own volume in me,
// this page adds them up, and this page is the only one that writes shared.
//
// How notes are given out: this page writes shared.parts, a list of phone and note pairs.
// A new phone gets the note with the fewest phones on it. A phone that leaves is taken off.
// If one note ends up with 2 more phones than another, one phone is moved. So the chord
// stays full at any size of class, and a phone's note rarely changes.
//
// Run this on the laptop that is on the projector, and open only one projector page for a room.
// Phones join with the code on the right.
//
// Try this:
//   Keys 1 2 3 4 change the chord. Every phone keeps its place and plays the new note.
//   Key M turns on a quiet monitor, so you can hear the mix on this laptop.
//   Raise one phone and watch its bar grow.
//
// Key data:
//   guests[i].vol                    one phone's volume, from 0 to 1
//   shared.parts[phoneId]            the note a phone plays. 0 is the lowest note
//   shared.chord                     { name, names, hz } the chord, for phones to read
//   shared.chordIndex                which of the four chords it is

const ROOM = 'chord';

// the chords. each has four notes, low to high, and the pitch of each in hertz.
// C, A minor, F and G7 are the chords of a very old song, and they fit one after another
let chords = [
  { name: 'C major', names: ['C4', 'E4', 'G4', 'C5'], hz: [261.63, 329.63, 392.00, 523.25] },
  { name: 'A minor', names: ['A3', 'C4', 'E4', 'A4'], hz: [220.00, 261.63, 329.63, 440.00] },
  { name: 'F major', names: ['F4', 'A4', 'C5', 'F5'], hz: [349.23, 440.00, 523.25, 698.46] },
  { name: 'G7', names: ['G4', 'B4', 'D5', 'F5'], hz: [392.00, 493.88, 587.33, 698.46] }
];
let chordIndex = 0;
let noteColors = ['#ffc800', '#3ddcff', '#ff6b9a', '#7cff8a'];
let monitorLevel = 0.18;   // how loud the quiet monitor is, from 0 to 1

let phoneKey = '';         // who is here now. when it changes, notes are given out again
let totals = [0, 0, 0, 0]; // the summed volume of the phones on each note
let counts = [0, 0, 0, 0]; // how many phones are on each note
let shown = [0, 0, 0, 0];  // the bars, which ease toward the totals
let joinedBefore = false;  // true once this page has been in the room
let monitorOn = false;
let monitor = [];          // four oscillators, made when the monitor is first turned on

function setup() {
  createCanvas(windowWidth, windowHeight);
  projectorSetup(ROOM, '02 Chord', { chordIndex: 0, parts: {} });
  layoutProjector();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  layoutProjector();
  showJoinCode();
}

// this runs each time the page joins the room, and again if it has to join again
function shareReady() {
  // a page that was just opened takes the chord the room already has, if it was reloaded.
  // a page that was running and joined again knows the chord better than the room does
  if (!joinedBefore && typeof shared.chordIndex === 'number') {
    chordIndex = shared.chordIndex;
  }
  joinedBefore = true;
  if (!shared.parts || typeof shared.parts !== 'object') {
    shared.parts = {};
  }
  writeChord();
  phoneKey = '';
}

function draw() {
  background(20);

  // 1. give out notes when the phones change. 2. add up the volumes. 3. draw the chord.
  const phones = phoneList();
  const key = phones.map(function (g) {
    return g.id;
  }).sort().join(',');
  if (shareConnected && key !== phoneKey) {
    phoneKey = key;
    giveOutNotes(phones);
  }
  addUpVolumes(phones);
  playMonitor();

  drawTitle('Each phone plays one note. Raise your phone to play louder.');
  drawKeys();
  drawChord(phones);
  drawJoinColumn('CHORD', chords[chordIndex].name, 64);
}

// the chord goes in shared as one object, so a phone never sees half of a change
function writeChord() {
  const c = chords[chordIndex];
  shared.chord = { name: c.name, names: c.names, hz: c.hz };
  shared.chordIndex = chordIndex;
}

// shared.parts says which note each phone plays
function giveOutNotes(phones) {
  const size = chords[chordIndex].names.length;
  const ids = phones.map(function (g) {
    return g.id;
  });
  const parts = shared.parts;

  // take off the phones that left
  Object.keys(parts).forEach(function (id) {
    if (ids.indexOf(id) < 0) {
      delete parts[id];
    }
  });

  // count how many phones are on each note
  const onNote = new Array(size).fill(0);
  ids.forEach(function (id) {
    if (parts[id] !== undefined && parts[id] < size) {
      onNote[parts[id]] += 1;
    }
  });

  // a new phone gets the note with the fewest phones on it
  ids.forEach(function (id) {
    if (parts[id] === undefined || parts[id] >= size) {
      const fewest = onNote.indexOf(Math.min(...onNote));
      parts[id] = fewest;
      onNote[fewest] += 1;
    }
  });

  // if one note has 2 more phones than another, move one phone across
  for (let tries = 0; tries < 50; tries++) {
    const most = onNote.indexOf(Math.max(...onNote));
    const least = onNote.indexOf(Math.min(...onNote));
    if (onNote[most] - onNote[least] < 2) {
      break;
    }
    const mover = ids.slice().reverse().find(function (id) {
      return parts[id] === most;
    });
    parts[mover] = least;
    onNote[most] -= 1;
    onNote[least] += 1;
  }
}

function addUpVolumes(phones) {
  const size = chords[chordIndex].names.length;
  totals = new Array(size).fill(0);
  counts = new Array(size).fill(0);
  for (let i = 0; i < phones.length; i++) {
    const note = shared.parts ? shared.parts[phones[i].id] : undefined;
    if (note !== undefined && note < size) {
      totals[note] += phones[i].vol || 0;
      counts[note] += 1;
    }
  }
}

// the quiet monitor. one oscillator for each note, as loud as the phones on that note
function playMonitor() {
  if (!monitorOn) {
    return;
  }
  const c = chords[chordIndex];
  const full = max(1, ceil(phoneList().length / c.names.length));
  for (let k = 0; k < monitor.length; k++) {
    monitor[k].freq(c.hz[k], 0.1);
    monitor[k].amp(constrain(totals[k] / full, 0, 1) * monitorLevel, 0.1);
  }
}

function toggleMonitor() {
  monitorOn = !monitorOn;
  if (monitorOn && monitor.length === 0) {
    userStartAudio();
    for (let k = 0; k < 4; k++) {
      const osc = new p5.Oscillator(chords[chordIndex].hz[k], 'triangle');
      osc.amp(0);
      osc.start();
      monitor.push(osc);
    }
  }
  if (!monitorOn) {
    for (let k = 0; k < monitor.length; k++) {
      monitor[k].amp(0, 0.1);
    }
  }
}

function keyPressed() {
  if (key >= '1' && key <= '4' && shareConnected) {
    chordIndex = int(key) - 1;
    writeChord();
  }
  if (key === 'm' || key === 'M') {
    toggleMonitor();
  }
}

// ---- drawing ----

function drawKeys() {
  noStroke();
  fill(GREY);
  textAlign(RIGHT, BASELINE);
  textSize(26 * u);
  let line = 'KEYS  1 2 3 4 change the chord     M monitor ';
  line += monitorOn ? 'on' : 'off';
  text(line, arena.x + arena.w, 84 * u);
  textAlign(LEFT, BASELINE);
}

function drawChord(phones) {
  const c = chords[chordIndex];
  const size = c.names.length;
  const gap = 24 * u;
  const w = (arena.w - gap * (size - 1)) / size;
  const full = max(1, ceil(phones.length / size)); // a full bar: every phone on the note, as loud as it goes

  const barTop = arena.y + 190 * u;
  const barBottom = arena.y + arena.h - 250 * u;
  const dotsTop = barBottom + 40 * u;

  for (let k = 0; k < size; k++) {
    const x = arena.x + k * (w + gap);
    const hue = noteColors[k];
    shown[k] = lerp(shown[k], constrain(totals[k] / full, 0, 1), 0.2);

    // the note and how many phones are on it
    noStroke();
    fill(hue);
    textAlign(LEFT, BASELINE);
    textStyle(BOLD);
    textSize(120 * u);
    text(c.names[k], x, arena.y + 110 * u);
    textStyle(NORMAL);
    fill(GREY);
    textSize(28 * u);
    const many = counts[k] === 1 ? '1 phone' : counts[k] + ' phones';
    text(many, x, arena.y + 156 * u);

    // the bar: the summed volume of the phones on this note
    fill(34);
    rect(x, barTop, w, barBottom - barTop);
    const h = shown[k] * (barBottom - barTop);
    const col = color(hue);
    col.setAlpha(220);
    fill(col);
    rect(x, barBottom - h, w, h);

    // one dot for each phone. a loud phone is a big bright dot
    const onThis = phones.filter(function (g) {
      return shared.parts && shared.parts[g.id] === k;
    });
    const perRow = max(1, floor((w - 10 * u) / (64 * u)));
    for (let i = 0; i < onThis.length; i++) {
      const vol = onThis[i].vol || 0;
      const cx = x + 32 * u + (i % perRow) * 64 * u;
      const cy = dotsTop + 34 * u + floor(i / perRow) * 64 * u;
      const dot = color(hue);
      dot.setAlpha(60 + vol * 195);
      fill(dot);
      circle(cx, cy, (14 + vol * 46) * u);
    }
  }

  if (phones.length === 0 && !serverProblem) {
    fill(255);
    textAlign(CENTER, CENTER);
    textSize(54 * u);
    text('Waiting for phones. Scan the code to join.', arena.x + arena.w / 2, arena.y + arena.h * 0.5);
    textAlign(LEFT, BASELINE);
  }
}
